```python
UNVISITED, ACTIVE, DONE = 0, 1, 2

def has_directed_cycle(adj):             # O(V + E).
    state = {v: UNVISITED for v in adj}
    def dfs(u):
        state[u] = ACTIVE                   # u is on the current path.
        for v in adj[u]:
            if state[v] == ACTIVE:          # back edge: cycle.
                return True
            if state[v] == UNVISITED and dfs(v):
                return True
        state[u] = DONE                     # leaving the path.
        return False
    return any(state[v] == UNVISITED and dfs(v) for v in adj)

def has_undirected_cycle(adj):
    seen = set()
    def dfs(u, parent):
        seen.add(u)
        for v in adj[u]:
            if v == parent:
                continue                   # the edge we arrived on.
            if v in seen or dfs(v, u):
                return True
        return False
    return any(v not in seen and dfs(v, None) for v in adj)
```

| Graph | Cycle evidence during DFS |
|---|---|
| undirected. | a visited neighbour that isn't the parent. |
| directed. | a neighbour in the ACTIVE state (back edge). |

